if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(($_SERVER['HTTP_ORIGIN']??'')!=='https://noastudio.ai.kr'||!hash_equals($_SESSION['noa_popularity_csrf'],$_SERVER['HTTP_X_NOA_POPULARITY_CSRF']??''))npa_reply(403,['ok'=>false,'error'=>'csrf_denied']);
