 try{$db=noa_bridge_pdo();$db->exec("SET time_zone='+00:00'");if(!np_ready($db))throw new DomainException('ranking_not_installed');$b=json_decode(file_get_contents('php://input',false,null,0,8193),true,32,JSON_THROW_ON_ERROR);$a=$b['action']??'';
  if($a==='rankings'){$hour=$b['hour']??null;if($hour!==null&&(!is_string($hour)||!preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:00:00$/D',$hour)))throw new DomainException('invalid_hour');npa_reply(200,np_public($db,(string)($b['type']??'featured'),1000,$hour));}
