  if($a!=='status')throw new DomainException('unknown_action');$run=$db->query("SELECT summary FROM noa_ranking_runs WHERE status='published' ORDER BY hour_utc DESC LIMIT 1")->fetchColumn();npa_reply(200,['ok'=>true,'latest'=>$run?json_decode($run,true):null,'policy'=>np_policy($db),'errors'=>$db->query('SELECT kind,code,hour_utc,created_at FROM noa_ranking_errors ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC),'history'=>$db->query("SELECT hour_utc,summary FROM noa_ranking_runs WHERE status='published' ORDER BY hour_utc DESC LIMIT 48")->fetchAll(PDO::FETCH_ASSOC),'excluded'=>$db->query("SELECT reason,COUNT(*) AS count FROM noa_play_sessions WHERE status='excluded' GROUP BY reason")->fetchAll(PDO::FETCH_ASSOC)]);
